(function mergeKanjiID(){
  const byJp = {};
  KANJI_ID_N5.forEach(e => { byJp[e.jp] = e; });
  KANJI_ID_N4.forEach(e => { byJp[e.jp] = e; });
  KANJI_ID_N3.forEach(e => { byJp[e.jp] = e; });
  KANJI_ID_N1.forEach(e => { byJp[e.jp] = e; });
  VOCAB.forEach(v => {
    if(v.type === "kanji"){
      const e = byJp[v.jp];
      if(e){
        v.meaning_id = e.meaning_id;
        v.onyomi = e.onyomi;
        v.kunyomi = e.kunyomi;
        v.contoh_gabungan = e.contoh;
      }
    }
  });
})();

/* ====== KANJI N2 (tahap 8) ======
   Kanji N2 sudah memiliki arti Indonesia bawaan di field "meaning" dan
   bacaan on'yomi/kun'yomi tergabung di field "romaji" (dipisah spasi/baris
   baru). Blok ini memisahkannya menjadi field yang sama seperti level lain,
   supaya tampilan flashcard-nya konsisten. */
(function extractN2KanjiReadings(){
  VOCAB.forEach(v => {
    if(v.type === "kanji" && v.level === "N2" && !v.meaning_id){
      v.meaning_id = v.meaning;
      const parts = v.romaji.split(/\s+/).filter(Boolean);
      v.onyomi = parts[0] || "";
      v.kunyomi = parts.slice(1).join(" ") || "";
    }
  });
})();
